import { randomUUID } from 'node:crypto';

import { type DatabasePool, type KeyProvider, withJobScope, withPracticeScope } from '@tp/db';
import { createLogger } from '@tp/observability';
import type { DocumentStore } from '@tp/worker/documents';
import { printReportDocument } from '@tp/worker/runtime';

import { coverageContent } from '../../reports/documents';

/**
 * Test support: a route-test world's report document (docs/adr/0045), for the Reports screen and the
 * document's page and downloads: a coverage report of the world's figures generated by its billing
 * manager, in their own name, and printed by the print job's code with a stand-in PDF. Synthetic data
 * only.
 */

export interface ReportWorldOptions {
  readonly app: DatabasePool;
  readonly keys: KeyProvider;
  readonly documents: DocumentStore;
  readonly practiceId: string;
  readonly managerId: string;
}

const standInPdf = () => new TextEncoder().encode(`%PDF-1.7\n% SYNTHETIC stand-in report document for the route tests ${randomUUID()}\n`);

export async function seedReportDocument(options: ReportWorldOptions): Promise<{ readonly reportDocumentId: string }> {
  const { practiceId } = options;
  const id = randomUUID();
  await withPracticeScope(options.app, { actorId: options.managerId, practiceIds: [practiceId] }, async (scope) => {
    const content = await coverageContent(scope, practiceId, new Date().toISOString().slice(0, 10), `test-${randomUUID()}`);
    await scope.client.query('INSERT INTO report_document (id, practice_id, kind, pricing_run_id, requested_by, content) VALUES ($1, $2, $3, $4, app_actor_id(), $5)', [
      id,
      practiceId,
      'coverage',
      content.run?.id ?? null,
      JSON.stringify(content),
    ]);
  });
  const jobId = randomUUID();
  const printed = await printReportDocument(
    { jobId, logger: createLogger({ sink: () => undefined }), transaction: (work) => withJobScope(options.app, { jobId, practiceId }, work), enqueue: () => Promise.resolve(null), lastAttempt: false },
    { documents: options.documents, keys: options.keys, pdf: { render: () => Promise.resolve(standInPdf()) } },
    practiceId,
    id,
  );
  if (printed.outcome !== 'printed') {
    throw new Error('the seeded report document was not printed');
  }
  return { reportDocumentId: id };
}
